          <div class="payu-sf-error-msg" id="payu-sf-cvv-error" aria-live="polite"></div>
        </div>
      </div>
    </div>

    <div class="payu-sf-installments" id="payu-sf-installments-panel" hidden>
      <div class="payu-sf-installments-title">Pay in installments</div>
      <div class="payu-sf-installments-provider" id="payu-sf-inst-provider"></div>
      <div class="payu-sf-installments-grid" id="payu-sf-inst-grid"></div>
      <div class="payu-sf-inst-min-note" id="payu-sf-inst-min-note"></div>
    </div>

    <button type="button" class="payu-sf-submit-btn" id="payu-sf-submit-btn" disabled>
      <div class="payu-sf-spinner"></div>
      <span class="payu-sf-btn-text">Pay now</span>
    </button>

    <div class="payu-sf-btn-group" id="payu-sf-new-card-btns" hidden>
      <button type="button" class="payu-sf-submit-btn" id="payu-sf-save-use-btn" disabled>
        <div class="payu-sf-spinner"></div>
        <span class="payu-sf-btn-text">Save and use</span>
      </button>
      <button type="button" class="payu-sf-submit-btn payu-sf-btn-use" id="payu-sf-use-btn" disabled>
        <div class="payu-sf-spinner"></div>
        <span class="payu-sf-btn-text">Use</span>
      </button>
    </div>

    <!-- A dedicated Secure Forms instance mounts the continuation CVV field here. -->
    <div class="payu-sf-cvv-continue" id="payu-sf-cvv-continue-container" hidden>
      <hr class="payu-sf-divider" />
      <div class="payu-sf-field-group">
        <label class="payu-sf-label">Enter CVV to confirm payment</label>
        <div class="payu-sf-input-host" id="payu-sf-cvv-continue-host"></div>
        <div class="payu-sf-error-msg" id="payu-sf-cvv-continue-error" aria-live="polite"></div>
      </div>
      <button type="button" class="payu-sf-submit-btn" id="payu-sf-cvv-confirm-btn" disabled>
        <div class="payu-sf-spinner"></div>
        <span class="payu-sf-btn-text">Confirm CVV</span>
      </button>
    </div>
    <div class="payu-sf-status" id="payu-sf-status" role="status" aria-live="polite"></div>
  </div>
</div>
","jsContent":"(function () {
  "use strict";

  var PAYU_CONFIG = {
    posId: OpfContext.vars.posId,
    currency: "RON",
    lang: "ro"
  };

  var PAYU_IFRAME_STYLE = {
    basic: { fontColor: "#1a1a2e", fontSize: "15", fontFamily: "-apple-system, BlinkMacSystemFont, 'Segoe UI', Roboto, sans-serif" },
    focus: { fontColor: "#1a1a2e" },
    placeholder: { fontColor: "#b0b7c9" }
  };

  function getSavedCards() {
    var rawTokens = OpfContext.customFields && OpfContext.customFields.cardTokens;
    if (!rawTokens) return [];
    var results = [];
    var regex = /#object=(\{[^}]+\})/g;
    var match;
    while ((match = regex.exec(String(rawTokens))) !== null) {
      try {
        var obj = JSON.parse(match[1]);
        if (String(obj.status) === "ACTIVE" && obj.value) {
          var maskedNumber = obj.cardNumberMasked ? String(obj.cardNumberMasked) : null;
          results.push({
            id: String(obj.value),
            brand: String(obj.cardBrand || "CARD").toLowerCase(),
            maskedNumber: maskedNumber,
            cardBin: maskedNumber ? maskedNumber.replace(/\D/g, "").slice(0, 6) : null,
            expiry: obj.cardExpirationMonth && obj.cardExpirationYear
              ? String(obj.cardExpirationMonth) + "/" + String(obj.cardExpirationYear) : "N/A",
            token: String(obj.value),
            brandImageUrl: obj.brandImageUrl ? String(obj.brandImageUrl) : null
          });
        }
      } catch (error) {
        console.error("getSavedCards: failed to parse a token object.");
      }
    }
    return results;
  }

  var state = {
    mode: "saved",
    selectedCard: null,
    ready: { number: false, date: false, cvv: false },
    valid: { number: false, date: false, cvv: false },
    touched: { number: false, date: false, cvv: false },
    installment: null,
    paymentLocked: false, // Keep normal controls disabled during payment.
    cvvActive: false // Show only the CVV continuation controls.
  };

  var el = {
    submitBtn: document.getElementById("payu-sf-submit-btn"),
    saveUseBtn: document.getElementById("payu-sf-save-use-btn"),
    useBtn: document.getElementById("payu-sf-use-btn"),
    newCardBtns: document.getElementById("payu-sf-new-card-btns"),
    statusEl: document.getElementById("payu-sf-status"),
    newCardFields: document.getElementById("payu-sf-new-card-fields"),
    installPanel: document.getElementById("payu-sf-installments-panel"),
    instProvider: document.getElementById("payu-sf-inst-provider"),
    instGrid: document.getElementById("payu-sf-inst-grid"),
    instMinNote: document.getElementById("payu-sf-inst-min-note"),
    savedList: document.getElementById("payu-sf-saved-list")
  };

  function setStatus(message, type) {
    if (!el.statusEl) return;
    el.statusEl.textContent = message || "";
    el.statusEl.className = "payu-sf-status" + (type ? " payu-sf--" + type : "");
  }

  function setLoading(loading, buttons) {
    state.paymentLocked = loading;
    buttons.forEach(function (button) {
      button.classList.toggle("payu-sf--loading", loading);
    });
    updateSubmitState();
  }

  function updateSubmitState() {
    var locked = state.paymentLocked || state.cvvActive;
    var saved = state.mode === "saved";
    var newCardValid = state.ready.number && state.ready.date && state.ready.cvv &&
      state.valid.number && state.valid.date && state.valid.cvv;

    el.submitBtn.hidden = state.cvvActive || !saved;
    el.newCardBtns.hidden = state.cvvActive || saved;
    el.newCardFields.hidden = state.cvvActive || saved;
    el.submitBtn.disabled = locked || !state.selectedCard;
    el.saveUseBtn.disabled = locked || !newCardValid;
    el.useBtn.disabled = locked || !newCardValid;
    el.savedList.querySelectorAll(".payu-sf-saved-card-btn").forEach(function (button) {
      button.disabled = locked;
    });
    el.instGrid.querySelectorAll(".payu-sf-inst-btn").forEach(function (button) {
      button.disabled = locked;
    });
    var newButton = document.getElementById("payu-sf-new-card-btn");
    if (newButton) {
      newButton.disabled = locked;
      newButton.hidden = state.cvvActive;
    }
    if (state.cvvActive) el.installPanel.hidden = true;
  }

  var ERROR_MESSAGES = {
    "error.validation.number": "Invalid card number.",
    "error.validation.expDate": "Invalid expiry date.",
    "error.validation.cvv": "Invalid CVV.",
    "error.validation.card.number": "Card number is required.",
    "error.validation.card.date": "Expiry date is required.",
    "error.validation.card.cvv": "CVV is required."
  };

  function friendlyError(errors) {
    if (!errors || !Array.isArray(errors) || !errors.length) return "";
    return errors.map(function (error) {
      return ERROR_MESSAGES[error.code] || error.message || error.code;
    }).join(" ");
  }

  function handleContinueCvv(redirectUri, buttons) {
    if (state.cvvActive) return;
    state.cvvActive = true;
    state.paymentLocked = true;
    buttons.forEach(function (button) { button.classList.remove("payu-sf--loading"); });
    updateSubmitState();

    var container = document.getElementById("payu-sf-cvv-continue-container");
    var confirmBtn = document.getElementById("payu-sf-cvv-confirm-btn");
    var errorEl = document.getElementById("payu-sf-cvv-continue-error");
    var ready = false;
    var valid = false;
    var sending = false;
    var checkingStatus = false;
    confirmBtn.disabled = true;
    container.hidden = false;

    try {
      if (!redirectUri || typeof redirectUri !== "string") {
        throw new Error("The CVV continuation URL is missing.");
      }
      var cvvPayuInstance = PayU(PAYU_CONFIG.posId);
      var refReqId = cvvPayuInstance.extractRefReqId(redirectUri);
      if (!refReqId) throw new Error("The CVV continuation reference is missing.");
      var cvvForms = cvvPayuInstance.secureForms();
      var cvvField = cvvForms.add("cvv", {
        style: PAYU_IFRAME_STYLE, lang: PAYU_CONFIG.lang, placeholder: "CVV"
      });

      function updateConfirmButton() {
        confirmBtn.disabled = !ready || !valid || sending;
      }
      cvvField.on("ready", function () {
        ready = true;
        updateConfirmButton();
      });
      cvvField.on("change", function (event) {
        valid = !!(event && event.error === false);
        errorEl.textContent = valid ? "" : friendlyError(event && event.error);
        updateConfirmButton();
      });

      confirmBtn.onclick = function (event) {
        event.preventDefault();
        if (confirmBtn.disabled || sending) return;
        sending = true;
        updateConfirmButton();
        confirmBtn.classList.add("payu-sf--loading");
        setStatus("Sending CVV…");

        Promise.resolve().then(function () {
          return cvvPayuInstance.sendCvv(refReqId);
        }).then(function () {
          // OPF determines the payment result after the SDK returns.
          checkingStatus = true;
          container.hidden = true;
          confirmBtn.classList.remove("payu-sf--loading");
          setStatus("Checking payment status…");
          return window.Opf.payments.checkout.submit({
            additionalData: [{ key: "requestType", value: "CONTINUE_CVV" }]
          });
        }).catch(function () {
          if (checkingStatus) {
            // Keep AUTH locked when the payment result is unknown.
            setStatus("Unable to check payment status.", "error");
          } else {
            sending = false;
            confirmBtn.classList.remove("payu-sf--loading");
            updateConfirmButton();
            setStatus("Unable to send CVV. Please try again.", "error");
          }
        });
      };

      cvvField.render("#payu-sf-cvv-continue-host");
      setStatus("Please enter your CVV to complete the payment.");
    } catch (error) {
      // An AUTH has already been submitted; keep normal payment actions locked.
      errorEl.textContent = error.message || "Unable to display the CVV form.";
      setStatus("Unable to continue payment. Please contact support.", "error");
    }
  }

  function makePayment(token, payuInstance, buttons) {
    var additionalData = [
      { key: "token", value: token },
      { key: "hasCardInstallment", value: !!state.installment },
      { key: "requestType", value: "AUTH" }
    ];
    if (state.installment) {
      additionalData.push({ key: "installmentProvider", value: state.installment.provider });
      additionalData.push({ key: "installmentNumber", value: state.installment.number });
    }
    try {
      var submission = window.Opf.payments.checkout.submit({
        additionalData: additionalData,
        submitSuccess: function () {
          setLoading(false, buttons);
        },
        submitPending: function (response) {
          // Do not unlock AUTH while CVV or 3DS continuation is required.
          if (response && response.customFields && response.customFields.length > 0) {
            var map = new Map(response.customFields.map(function (field) { return [field.key, field.value]; }));
            var redirectURI = map.get("redirectURI");
            var statusCode = map.get("statusCode");
            if (statusCode === "WARNING_CONTINUE_CVV") {
              handleContinueCvv(redirectURI, buttons);
              return;
            }
            if (redirectURI) window.Opf.payments.checkout.handle3DSRedirect(redirectURI);
          }
        },
        submitFailure: function () {
          if (!state.cvvActive) setLoading(false, buttons);
          setStatus("Payment failed.", "error");
        },
        submitCancel: function () {
          window.location.href = "/checkout/opf-payment-and-review";
        }
      });
      if (submission && typeof submission.catch === "function") {
        submission.catch(function () {
          // OPF handles the failure; do not automatically retry AUTH.
          console.error("Payment submission failed.");
        });
      }
    } catch (error) {
      setStatus("Unable to continue payment.", "error");
    }
  }

  function renderInstallments(data) {
    if (state.paymentLocked || state.cvvActive) return;
    var hasRealInstallments = data && data.numbers && data.numbers.some(function (number) { return number > 1; });
    if (!hasRealInstallments) {
      el.installPanel.hidden = true;
      state.installment = null;
      return;
    }
    el.instProvider.textContent = "Provider: " + (data.provider || "—");
    el.instMinNote.textContent = data.settings && data.settings.minAmount
      ? "Minimum order amount for installments: " + PAYU_CONFIG.currency + " " + (data.settings.minAmount / 100).toFixed(2) : "";
    el.instGrid.innerHTML = "";
    data.numbers.forEach(function (number) {
      var button = document.createElement("button");
      button.type = "button";
      button.className = "payu-sf-inst-btn";
      button.textContent = number === 1 ? "Full payment" : number + "× installments";
      if (number === 1) { button.classList.add("payu-sf--selected"); state.installment = null; }
      button.addEventListener("click", function () {
        if (state.paymentLocked || state.cvvActive) return;
        el.instGrid.querySelectorAll(".payu-sf-inst-btn").forEach(function (item) { item.classList.remove("payu-sf--selected"); });
        button.classList.add("payu-sf--selected");
        state.installment = number === 1 ? null : { provider: data.provider, number: number };
        setStatus("");
      });
      el.instGrid.appendChild(button);
    });
    el.installPanel.hidden = false;
  }

  function retrieveCardInstallments(cardBin) {
    var submission = window.Opf.payments.checkout.submit({
      additionalData: [
        { key: "cardBin", value: cardBin },
        { key: "requestType", value: "INSTALLMENTS" }
      ],
      submitSuccess: function () {},
      submitPending: function (response) {
        if (state.paymentLocked || state.cvvActive || state.mode !== "saved" ||
            !state.selectedCard || state.selectedCard.cardBin !== cardBin) return;
        if (response && response.customFields && response.customFields.length > 0) {
          var map = new Map(response.customFields.map(function (field) { return [field.key, field.value]; }));
          var provider = map.get("cardInstallmentsProvider");
          try {
            var numbers = JSON.parse(map.get("cardInstallmentsNumber") || "[]");
            if (provider && Array.isArray(numbers) && numbers.length) renderInstallments({ provider: provider, numbers: numbers });
          } catch (error) { console.error("Invalid installment response."); }
        }
      },
      submitFailure: function () { console.error("Unable to retrieve card installments."); },
      submitCancel: function () { window.location.href = "/checkout/opf-payment-and-review"; }
    });
    if (submission && typeof submission.catch === "function") {
      submission.catch(function () { console.error("Unable to retrieve card installments."); });
    }
  }

  function renderSavedCards() {
    el.savedList.innerHTML = "";
    getSavedCards().forEach(function (card) {
      var button = document.createElement("button");
      button.type = "button";
      button.className = "payu-sf-saved-card-btn";
      button.dataset.cardId = card.id;
      button.innerHTML =
        (card.brandImageUrl
          ? '<img class="payu-sf-brand-img" src="' + card.brandImageUrl + '" alt="' + card.brand + '">'
          : '<span class="payu-sf-brand-badge ' + card.brand + '">' + card.brand.toUpperCase() + '</span>') +
        '<span class="payu-sf-card-meta">' +
        '<span class="payu-sf-card-digits">' + (card.maskedNumber || "•••• •••• •••• ••••") + '</span>' +
        '<span class="payu-sf-card-exp">Expires ' + card.expiry + '</span>' +
        '</span>' +
        '<span class="payu-sf-card-tick">' +
        '<svg viewBox="0 0 12 10" fill="none"><polyline points="1,5 4.5,8.5 11,1" stroke="#fff" stroke-width="2" stroke-linecap="round" stroke-linejoin="round"/></svg>' +
        '</span>';
      button.addEventListener("click", function () { pickSavedCard(card); });
      el.savedList.appendChild(button);
    });
    var newButton = document.createElement("button");
    newButton.type = "button";
    newButton.id = "payu-sf-new-card-btn";
    newButton.className = "payu-sf-new-card-btn";
    newButton.innerHTML = '<svg viewBox="0 0 16 16" width="14" height="14" fill="currentColor"><path d="M8 1a.75.75 0 0 1 .75.75v5.5h5.5a.75.75 0 0 1 0 1.5h-5.5v5.5a.75.75 0 0 1-1.5 0v-5.5H1.75a.75.75 0 0 1 0-1.5h5.5V1.75A.75.75 0 0 1 8 1z"/></svg>New card';
    newButton.addEventListener("click", pickNewCard);
    el.savedList.appendChild(newButton);
  }

  function setSavedListHighlight(cardId) {
    el.savedList.querySelectorAll(".payu-sf-saved-card-btn").forEach(function (button) {
      button.classList.toggle("payu-sf--selected", button.dataset.cardId === cardId);
    });
    var newButton = document.getElementById("payu-sf-new-card-btn");
    if (newButton) newButton.classList.toggle("payu-sf--selected", cardId === "__new__");
  }

  function pickSavedCard(card) {
    if (state.paymentLocked || state.cvvActive) return;
    state.mode = "saved";
    state.selectedCard = card;
    setSavedListHighlight(card.id);
    el.newCardFields.hidden = true;
    el.installPanel.hidden = true;
    state.installment = null;
    setStatus("");
    updateSubmitState();
    if (card.cardBin) retrieveCardInstallments(card.cardBin);
  }

  function pickNewCard() {
    if (state.paymentLocked || state.cvvActive) return;
    state.mode = "new";
    state.selectedCard = null;
    state.installment = null;
    state.valid = { number: false, date: false, cvv: false };
    state.touched = { number: false, date: false, cvv: false };
    // Clear input values while preserving iframe readiness.
    cardNumber.clear();
    cardDate.clear();
    cardCvv.clear();
    ["number", "date", "cvv"].forEach(function (name) {
      document.getElementById("payu-sf-" + name + "-host").classList.remove("payu-sf--invalid", "payu-sf--focus");
      document.getElementById("payu-sf-" + name + "-error").textContent = "";
    });
    setSavedListHighlight("__new__");
    el.installPanel.hidden = true;
    el.instGrid.innerHTML = "";
    el.instProvider.textContent = "";
    el.instMinNote.textContent = "";
    setStatus("");
    updateSubmitState();
  }

  function wireField(name, sdkField) {
    var host = document.getElementById("payu-sf-" + name + "-host");
    var errorEl = document.getElementById("payu-sf-" + name + "-error");
    sdkField.on("ready", function () { state.ready[name] = true; updateSubmitState(); });
    sdkField.on("focus", function () { host.classList.add("payu-sf--focus"); });
    sdkField.on("blur", function () {
      host.classList.remove("payu-sf--focus");
      state.touched[name] = true;
      if (!state.valid[name]) host.classList.add("payu-sf--invalid");
    });
    sdkField.on("change", function (event) {
      var valid = !!(event && event.error === false);
      state.valid[name] = valid;
      if (state.touched[name]) {
        host.classList.toggle("payu-sf--invalid", !valid);
        errorEl.textContent = valid ? "" : friendlyError(event && event.error);
      } else if (valid) {
        host.classList.remove("payu-sf--invalid");
        errorEl.textContent = "";
      }
      updateSubmitState();
    });
  }

  var payuInstance = PayU(PAYU_CONFIG.posId);
  var secureForms = payuInstance.secureForms();
  var cardNumber = secureForms.add("number", { style: PAYU_IFRAME_STYLE, lang: PAYU_CONFIG.lang, enableInstallments: true, placeholder: "1234 5678 9012 3456" });
  var cardDate = secureForms.add("date", { style: PAYU_IFRAME_STYLE, lang: PAYU_CONFIG.lang, placeholder: "MM / YY" });
  var cardCvv = secureForms.add("cvv", { style: PAYU_IFRAME_STYLE, lang: PAYU_CONFIG.lang, placeholder: "CVV" });
  wireField("number", cardNumber);
  wireField("date", cardDate);
  wireField("cvv", cardCvv);
  cardNumber.on("installmentsChange", function (data) {
    if (state.mode === "new") renderInstallments(data);
  });
  cardNumber.render("#payu-sf-number-host");
  cardDate.render("#payu-sf-date-host");
  cardCvv.render("#payu-sf-cvv-host");
  renderSavedCards();
  updateSubmitState();

  function handleNewCardSubmit(tokenType, activeBtn) {
    if (state.paymentLocked || state.cvvActive || activeBtn.disabled) return;
    setLoading(true, [activeBtn]);
    setStatus("Processing payment…");
    Promise.resolve().then(function () { return payuInstance.tokenize(tokenType); })
      .then(function (result) {
        if (!result || result.status !== "SUCCESS" || !result.body || !result.body.token) {
          throw new Error("Tokenization failed.");
        }
        setStatus("Token acquired. Submitting order…");
        makePayment(result.body.token, payuInstance, [activeBtn]);
      }).catch(function () {
        setLoading(false, [activeBtn]);
        setStatus("Tokenization failed. Please check your card details and try again.", "error");
      });
  }

  el.submitBtn.addEventListener("click", function (event) {
    event.preventDefault();
    if (el.submitBtn.disabled || state.paymentLocked || state.cvvActive || !state.selectedCard) return;
    setLoading(true, [el.submitBtn]);
    setStatus("Processing payment…");
    makePayment(state.selectedCard.token, payuInstance, [el.submitBtn]);
  });
  el.saveUseBtn.addEventListener("click", function (event) {
    event.preventDefault();
    if (el.saveUseBtn.disabled) return;
    handleNewCardSubmit("MULTI", el.saveUseBtn);
  });
  el.useBtn.addEventListener("click", function (event) {
    event.preventDefault();
    if (el.useBtn.disabled) return;
    handleNewCardSubmit("SINGLE", el.useBtn);
  });
})();
","jsHash":"sha384-wYfsGihVDvGSQdpilGOmjTBnEnhmbQQV2ukQeNxEIa4gHwkb/pdeiiKP5O4SeZZ5","jsContextFields":[{"path":"${input.contentLanguage}"},{"path":"${vars.posId}"},{"path":"${input.customFields.cardTokens}"},{"path":"${input.transactionId}"}],"cssContent":"/* Load as the stylesheet for the OPF payment fragment. */

/* Reset scoped to this widget: leave the surrounding storefront body intact. */
.payu-sf-wrapper *,
.payu-sf-wrapper *::before,
.payu-sf-wrapper *::after {
  box-sizing: border-box;
  margin: 0;
  padding: 0;
}

.payu-sf-wrapper {
  font-family: -apple-system, BlinkMacSystemFont, "Segoe UI", Roboto, sans-serif;
  font-size: 14px;
  color: #1a1a2e;
  width: 100%;
  min-width: 0;
}

.payu-sf-card {
  padding: 32px 28px;
  width: 100%;
  min-width: 0;
}

/* Header */
.payu-sf-header {
  display: flex;
  align-items: center;
  gap: 10px;
  margin-bottom: 24px;
}

.payu-sf-header > div:last-child { min-width: 0; }
.payu-sf-logo {
  width: 36px;
  height: 36px;
  background: #6c47ff;
  border-radius: 8px;
  display: flex;
  align-items: center;
  justify-content: center;
  flex-shrink: 0;
}
.payu-sf-logo svg { width: 20px; height: 20px; fill: #fff; }
.payu-sf-title { font-size: 18px; font-weight: 600; color: #1a1a2e; }
.payu-sf-subtitle { font-size: 12px; color: #8892a4; margin-top: 1px; }

.payu-sf-label {
  display: block;
  font-size: 12px;
  font-weight: 500;
  color: #5a5f7a;
  text-transform: uppercase;
  letter-spacing: 0.06em;
  margin-bottom: 6px;
}

/* Saved cards */
.payu-sf-saved-section { margin-bottom: 20px; }
.payu-sf-saved-list { display: flex; flex-direction: column; gap: 6px; }
.payu-sf-saved-card-btn,
.payu-sf-new-card-btn {
  appearance: none;
  display: flex;
  align-items: center;
  width: 100%;
  min-height: 44px;
  background: #fff;
  border-radius: 8px;
  cursor: pointer;
  font-family: inherit;
  transition: border-color 0.2s, box-shadow 0.2s, background 0.2s;
}
.payu-sf-saved-card-btn:hover:not(:disabled),
.payu-sf-new-card-btn:hover:not(:disabled) {
  border-color: #6c47ff;
  background: #f8f6ff;
}
.payu-sf-saved-card-btn.payu-sf--selected,
.payu-sf-new-card-btn.payu-sf--selected {
  border-color: #6c47ff;
  background: #f3f0ff;
  box-shadow: 0 0 0 3px rgba(108, 71, 255, 0.12);
}
.payu-sf-saved-card-btn {
  gap: 10px;
  padding: 10px 14px;
  border: 1.5px solid #dde2f0;
  text-align: left;
}
.payu-sf-brand-badge {
  flex-shrink: 0;
  width: 34px;
  height: 22px;
  border-radius: 4px;
  display: flex;
  align-items: center;
  justify-content: center;
  font-size: 9px;
  font-weight: 800;
  letter-spacing: 0.03em;
  color: #fff;
  background: #8892a4;
}
.payu-sf-brand-img {
  flex-shrink: 0;
  width: 34px;
  height: 22px;
  object-fit: contain;
  border-radius: 4px;
}
.payu-sf-card-meta {
  flex: 1;
  min-width: 0;
  display: flex;
  align-items: baseline;
  gap: 6px;
  justify-content: space-between;
}
.payu-sf-card-digits {
  font-size: 13px;
  font-weight: 600;
  color: #1a1a2e;
  letter-spacing: 0.06em;
  overflow-wrap: anywhere;
}
.payu-sf-card-exp { font-size: 11px; color: #8892a4; white-space: nowrap; }
.payu-sf-card-tick {
  flex-shrink: 0;
  width: 18px;
  height: 18px;
  border-radius: 50%;
  background: #6c47ff;
  display: none;
  align-items: center;
  justify-content: center;
}
.payu-sf-saved-card-btn.payu-sf--selected .payu-sf-card-tick { display: flex; }
.payu-sf-card-tick svg { width: 10px; height: 10px; }
.payu-sf-new-card-btn {
  gap: 8px;
  padding: 10px 14px;
  border: 1.5px dashed #c4b0ff;
  font-size: 13px;
  font-weight: 500;
  color: #6c47ff;
}

/* Fields shared by new cards and CVV continuation. */
.payu-sf-divider {
  border: none;
  border-top: 1px solid #eef0f8;
  margin: 16px 0 20px;
}
.payu-sf-field-group { margin-bottom: 16px; min-width: 0; }
.payu-sf-input-host {
  height: 48px;
  width: 100%;
  min-width: 0;
  border: 1.5px solid #dde2f0;
  border-radius: 8px;
  background: #fff;
  transition: border-color 0.2s, box-shadow 0.2s;
}
.payu-sf-input-host.payu-sf--focus {
  border-color: #6c47ff;
  box-shadow: 0 0 0 3px rgba(108, 71, 255, 0.12);
}
.payu-sf-input-host.payu-sf--invalid {
  border-color: #e53e3e;
  box-shadow: 0 0 0 3px rgba(229, 62, 62, 0.10);
}
.payu-sf-row-half {
  display: grid;
  grid-template-columns: minmax(0, 1fr) minmax(0, 1fr);
  gap: 12px;
}
.payu-sf-error-msg {
  font-size: 11px;
  color: #e53e3e;
  margin-top: 4px;
  min-height: 14px;
  overflow-wrap: anywhere;
}
.payu-sf-cvv-continue { width: 100%; }
.payu-sf-cvv-continue .payu-sf-label { line-height: 1.5; }

/* Installments */
.payu-sf-installments {
  background: #f8f6ff;
  border: 1.5px solid #d4c5ff;
  border-radius: 8px;
  padding: 16px;
  margin-bottom: 16px;
  animation: payu-sf-fadein 0.3s ease;
}
.payu-sf-installments-title { font-size: 13px; font-weight: 600; color: #4a2cad; margin-bottom: 4px; }
.payu-sf-installments-provider { font-size: 11px; color: #7b5ea7; margin-bottom: 12px; }
.payu-sf-installments-grid { display: flex; flex-wrap: wrap; gap: 8px; }
.payu-sf-inst-btn {
  appearance: none;
  border: 1.5px solid #c4b0ff;
  background: #fff;
  border-radius: 6px;
  padding: 6px 14px;
  min-height: 36px;
  font-family: inherit;
  font-size: 13px;
  font-weight: 500;
  color: #4a2cad;
  cursor: pointer;
  transition: background 0.15s, border-color 0.15s, color 0.15s;
  line-height: 1.4;
}
.payu-sf-inst-btn:hover:not(:disabled) { background: #ede8ff; border-color: #6c47ff; }
.payu-sf-inst-btn.payu-sf--selected { background: #6c47ff; border-color: #6c47ff; color: #fff; }
.payu-sf-inst-min-note { font-size: 11px; color: #9a8abf; margin-top: 8px; }

/* Payment and confirmation buttons */
.payu-sf-submit-btn {
  appearance: none;
  width: 100%;
  min-height: 48px;
  padding: 14px;
  background: #6c47ff;
  color: #fff;
  border: none;
  border-radius: 8px;
  font-family: inherit;
  font-size: 15px;
  font-weight: 600;
  cursor: pointer;
  transition: background 0.2s, transform 0.1s;
  display: flex;
  align-items: center;
  justify-content: center;
  gap: 8px;
}
.payu-sf-submit-btn:hover:not(:disabled) { background: #5433d6; }
.payu-sf-submit-btn:active:not(:disabled) { transform: scale(0.99); }
.payu-sf-submit-btn:disabled { opacity: 0.6; cursor: not-allowed; }
.payu-sf-btn-group { display: flex; flex-direction: column; gap: 10px; }
.payu-sf-btn-use { background: #fff; color: #6c47ff; border: 1.5px solid #6c47ff; }
.payu-sf-btn-use:hover:not(:disabled) { background: #f3f0ff; border-color: #5433d6; color: #5433d6; }

/* Locked cards keep their visual identity and selected state during continuation. */
.payu-sf-saved-card-btn:disabled,
.payu-sf-new-card-btn:disabled,
.payu-sf-inst-btn:disabled { cursor: default; opacity: 1; }
.payu-sf-wrapper button:focus-visible { outline: 2px solid #6c47ff; outline-offset: 3px; }

/* Spinner */
.payu-sf-spinner {
  flex-shrink: 0;
  width: 16px;
  height: 16px;
  border: 2px solid rgba(255, 255, 255, 0.4);
  border-top-color: #fff;
  border-radius: 50%;
  animation: payu-sf-spin 0.7s linear infinite;
  display: none;
}
.payu-sf-submit-btn.payu-sf--loading .payu-sf-spinner { display: block; }
.payu-sf-submit-btn.payu-sf--loading .payu-sf-btn-text { opacity: 0.7; }
.payu-sf-btn-use .payu-sf-spinner { border-color: rgba(108, 71, 255, 0.3); border-top-color: #6c47ff; }
.payu-sf-status {
  margin-top: 12px;
  font-size: 13px;
  text-align: center;
  min-height: 18px;
  line-height: 1.5;
  color: #5a5f7a;
  overflow-wrap: anywhere;
}
.payu-sf-status.payu-sf--error { color: #e53e3e; }
.payu-sf-status.payu-sf--success { color: #16a34a; font-weight: 500; }

@keyframes payu-sf-spin { to { transform: rotate(360deg); } }
@keyframes payu-sf-fadein {
  from { opacity: 0; transform: translateY(-4px); }
  to { opacity: 1; transform: translateY(0); }
}

/* Mobile browser layout */
@media (max-width: 480px) {
  .payu-sf-card { padding: 24px 16px; }
  .payu-sf-header { align-items: flex-start; }
  .payu-sf-title { font-size: 17px; }
  .payu-sf-subtitle { line-height: 1.5; }
  .payu-sf-saved-card-btn { padding: 10px; gap: 8px; }
  .payu-sf-card-meta { flex-direction: column; align-items: flex-start; gap: 3px; }
}
@media (prefers-reduced-motion: reduce) {
  .payu-sf-wrapper *,
  .payu-sf-wrapper *::before,
  .payu-sf-wrapper *::after { transition: none; animation: none; }
}

/* Required for JS .hidden: display:flex would otherwise override browser defaults.
   Applies to Pay now, New card, the CVV container, and all other hidden panels. */
.payu-sf-wrapper [hidden] { display: none !important; }
